<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Lotte Tower Artwork</title>
    <style>
        body { font-family: Arial, sans-serif; }
       .container { display: flex; flex-direction: column; align-items: center; }
       .canvas-container { width: 80%; height: 600px; margin: 20px 0; }
       .controls { margin-bottom: 20px; }
       .control-label { font-size: 19px; margin-right: 10px; }
       .control-button { font-size: 19px; padding: 10px; cursor: pointer; }
       .drawing { width: 80%; height: 400px; margin: 20px 0; }
    </style>
</head>
<body>
    <div class="container">
        <div class="canvas-container">
            <canvas id="canvas"></canvas>
        </div>
        <div class="controls">
            <label class="control-label" for="rotate">Rotate</label>
            <button class="control-button" id="rotate-left">Left</button>
            <button class="control-button" id="rotate-right">Right</button>
            <label class="control-label" for="zoom">Zoom</label>
            <button class="control-button" id="zoom-in">In</button>
            <button class="control-button" id="zoom-out">Out</button>
        </div>
        <div class="drawing">
            <img src="site-plan.png" alt="Site Plan">
            <img src="floor-plan.png" alt="Floor Plan">
            <img src="elevation.png" alt="Elevation">
            <img src="section.png" alt="Section">
        </div>
    </div>
    <script>
        const canvas = document.getElementById('canvas');
        const ctx = canvas.getContext('2d');
        let angle = 0;
        let scale = 1;

        function draw() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            ctx.save();
            ctx.translate(canvas.width / 2, canvas.height / 2);
            ctx.rotate(angle);
            ctx.scale(scale, scale);
            // Draw your 3D geometry here
            ctx.restore();
            requestAnimationFrame(draw);
        }

        document.getElementById('rotate-left').addEventListener('click', () => {
            angle -= 0.1;
        });

        document.getElementById('rotate-right').addEventListener('click', () => {
            angle += 0.1;
        });

        document.getElementById('zoom-in').addEventListener('click', () => {
            scale *= 1.1;
        });

        document.getElementById('zoom-out').addEventListener('click', () => {
            scale *= 0.9;
        });

        draw();
    </script>
</body>
</html>
